import { useRef, useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  getGoodsList,
  updateGoodsStatus,
  batchUpdateGoodsStatus,
  GoodsTypes
} from '@/apis/admin/goods'
import { getServiceTypeList } from '@/apis/admin/system-config'
import ExcelTable from '@/components/exportExcel'
import { ActionType, ProColumns } from '@ant-design/pro-components'
import {
  Button,
  Popconfirm,
  message,
  Tag,
  Space,
  Modal,
  Descriptions
} from 'antd'
import {
  EyeOutlined,
  EditOutlined,
  PlusOutlined,
  ArrowUpOutlined,
  ArrowDownOutlined,
  DeleteOutlined,
  AppstoreOutlined,
} from '@ant-design/icons'
import { Tooltip } from 'antd'
import { ResultEnum } from '@/utils/enums/httpEnum'

// 格口规格映射
const gridSpecMap: Record<number, { text: string; color: string }> = {
  1: { text: '小格', color: 'blue' },
  2: { text: '中格', color: 'orange' },
  3: { text: '大格', color: 'green' },
}

// 商品状态映射
const goodsStatusMap: Record<number, { text: string; color: string }> = {
  1: { text: '上架中', color: 'success' },
  2: { text: '已下架', color: 'default' },
}

const ProductList: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const navigate = useNavigate()
  const [serviceTypeOptions, setServiceTypeOptions] = useState<Record<string, { text: string }>>({})
  const [detailModalVisible, setDetailModalVisible] = useState(false)
  const [selectedGoods, setSelectedGoods] = useState<GoodsTypes.GoodsListDto | null>(null)
  const [selectedRowKeys, setSelectedRowKeys] = useState<number[]>([])

  // 加载服务类型列表
  const loadServiceTypeList = async () => {
    try {
      const res = await getServiceTypeList({ status: 1, pageSize: 100 })
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        // 转换为 valueEnum 格式
        const options: Record<string, { text: string }> = {}
        res.data.list.forEach((item) => {
          options[item.id] = { text: item.name }
        })
        setServiceTypeOptions(options)
      }
    } catch (e) {
      console.error('获取服务类型列表失败:', e)
    }
  }

  // 组件挂载时加载服务类型列表
  useEffect(() => {
    loadServiceTypeList()
  }, [])

  // 新增商品
  const handleAddGoods = () => {
    navigate('/product/edit/0')
  }

  // 编辑商品
  const handleEditGoods = (record: GoodsTypes.GoodsListDto) => {
    navigate(`/product/edit/${record.id}`)
  }

  // 查看商品详情
  const handleViewDetail = (record: GoodsTypes.GoodsListDto) => {
    setSelectedGoods(record)
    setDetailModalVisible(true)
  }

  // 更新商品状态（上架/下架/删除）
  const handleUpdateStatus = async (record: GoodsTypes.GoodsListDto, status: 1 | 2 | 3) => {
    try {
      const res = await updateGoodsStatus(record.id, {
        goodsId: record.id,
        goodsStatus: status
      })
      if (res.code === ResultEnum.SUCCESS) {
        message.success(status === 3 ? '删除成功' : '状态更新成功')
        actionRef.current?.reload()
      } else {
        message.error('操作失败')
      }
    } catch (e) {
      console.error('更新商品状态失败:', e)
      message.error('操作失败')
    }
  }

  // 批量更新状态
  const handleBatchUpdateStatus = async (status: 1 | 2) => {
    if (selectedRowKeys.length === 0) {
      message.warning('请先选择商品')
      return
    }
    try {
      const res = await batchUpdateGoodsStatus({
        goodsIdArr: selectedRowKeys,
        goodsStatus: status
      })
      if (res.code === ResultEnum.SUCCESS) {
        message.success(`已批量${status === 1 ? '上架' : '下架'}`)
        setSelectedRowKeys([])
        actionRef.current?.reload()
      } else {
        message.error('操作失败')
      }
    } catch (e) {
      console.error('批量更新商品状态失败:', e)
      message.error('操作失败')
    }
  }

  // 表格列定义
  const columns: ProColumns<GoodsTypes.GoodsListDto>[] = [
    {
      title: '商品编号',
      dataIndex: 'goodsSn',
      key: 'goodsSn',
      width: 140,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>
          {text}
        </span>
      ),
    },
    {
      title: '商品名称',
      dataIndex: 'goodsName',
      key: 'goodsName',
      width: 160,
    },
    {
      title: '格口规格',
      dataIndex: 'gridSpec',
      key: 'gridSpec',
      width: 100,
      valueType: 'select',
      valueEnum: {
        1: { text: '小格' },
        2: { text: '中格' },
        3: { text: '大格' },
      },
      render: (_, record) => {
        const spec = gridSpecMap[record.gridSpec]
        return <Tag color={spec?.color || 'default'}>{spec?.text || '未知'}</Tag>
      },
    },
    {
      title: '服务类型',
      dataIndex: 'serviceTypeId',
      key: 'serviceTypeId',
      width: 120,
      hideInTable: true,
      valueType: 'select',
      valueEnum: serviceTypeOptions,
    },
    {
      title: '服务类型',
      dataIndex: 'serviceTypeName',
      key: 'serviceTypeName_display',
      width: 120,
      hideInSearch: true,
    },
    {
      title: '成本价',
      dataIndex: 'costPrice',
      key: 'costPrice',
      width: 100,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>
          ¥{Number(text).toFixed(2)}
        </span>
      ),
    },
    {
      title: '初始价格',
      dataIndex: 'initialPrice',
      key: 'initialPrice',
      width: 100,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>
          ¥{Number(text).toFixed(2)}
        </span>
      ),
    },
    {
      title: '超时价格',
      dataIndex: 'overtimePrice',
      key: 'overtimePrice',
      width: 110,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>
          ¥{Number(text).toFixed(2)}/天
        </span>
      ),
    },
    {
      title: '免费天数',
      dataIndex: 'freeDays',
      key: 'freeDays',
      width: 90,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>{text}天</span>
      ),
    },
    {
      title: '积分抵扣',
      dataIndex: 'pointDeduct',
      key: 'pointDeduct',
      width: 100,
      hideInSearch: true,
      render: (text) => (
        text === 1 ? <Tag color="success">支持</Tag> : <Tag>不支持</Tag>
      ),
    },
    {
      title: '抵扣上限',
      dataIndex: 'pointDeductLimit',
      key: 'pointDeductLimit',
      width: 100,
      hideInSearch: true,
      render: (text, record) => (
        record.pointDeduct === 1 ? (
          <span style={{ fontFamily: 'Courier New, monospace' }}>{text}%</span>
        ) : '-'
      ),
    },
    {
      title: '状态',
      dataIndex: 'goodsStatus',
      key: 'goodsStatus',
      width: 100,
      valueType: 'select',
      valueEnum: {
        1: { text: '上架中', status: 'Success' },
        2: { text: '已下架', status: 'Default' },
      },
      render: (_, record) => {
        const status = goodsStatusMap[record.goodsStatus]
        return <Tag color={status?.color || 'default'}>{status?.text || '未知'}</Tag>
      },
    },
    {
      title: '操作',
      key: 'option',
      valueType: 'option',
      fixed: 'right',
      width: 140,
      render: (_, record) => [
        <Tooltip title="查看" key={`${record.id}-view`}>
          <Button
            type="link"
            title="查看"
            icon={<EyeOutlined />}
            onClick={() => handleViewDetail(record)}
          />
        </Tooltip>,
        <Tooltip title="编辑" key={`${record.id}-edit`}>
          <Button
            type="link"
            title="编辑"
            icon={<EditOutlined />}
            onClick={() => handleEditGoods(record)}
          />
        </Tooltip>,
        record.goodsStatus === 1 ? (
          <Tooltip title="下架" key={`${record.id}-off`}>
            <Popconfirm
              title="确定要下架该商品吗？"
              onConfirm={() => handleUpdateStatus(record, 2)}
              okText="确定"
              cancelText="取消"
            >
              <Button type="link" danger title="下架" icon={<ArrowDownOutlined />} />
            </Popconfirm>
          </Tooltip>
        ) : (
          <Tooltip title="上架" key={`${record.id}-on`}>
            <Button
              type="link"
              title="上架"
              icon={<ArrowUpOutlined />}
              style={{ color: '#52c41a' }}
              onClick={() => handleUpdateStatus(record, 1)}
            />
          </Tooltip>
        ),
        <Tooltip title="删除" key={`${record.id}-delete`}>
          <Popconfirm
            title="确定要删除该商品吗？删除后将无法恢复。"
            onConfirm={() => handleUpdateStatus(record, 3)}
            okText="确定"
            cancelText="取消"
          >
            <Button type="link" danger title="删除" icon={<DeleteOutlined />} />
          </Popconfirm>
        </Tooltip>,
      ],
    },
  ]

  return (
    <>
      <ExcelTable
        key="goods-list"
        columns={columns}
        requestFn={async (params) => {
          const { page, pageSize, goodsName, goodsStatus, serviceTypeId } = params
          return await getGoodsList({
            page,
            pageSize,
            goodsName,
            goodsStatus,
            serviceTypeId
          })
        }}
        actionRef={actionRef}
        rowSelection={{
          selectedRowKeys,
          onChange: (keys) => setSelectedRowKeys(keys as number[]),
        }}
        options={{
          fullScreen: false,
          reload: true,
          setting: false,
          density: false
        }}
        toolBarRenderFn={() => [
          <Button
            key="add"
            type="primary"
            icon={<PlusOutlined />}
            onClick={handleAddGoods}
          >
            新增商品
          </Button>,
          <Button
            key="batch-on"
            icon={<ArrowUpOutlined />}
            onClick={() => handleBatchUpdateStatus(1)}
          >
            批量上架
          </Button>,
          <Button
            key="batch-off"
            icon={<ArrowDownOutlined />}
            onClick={() => handleBatchUpdateStatus(2)}
          >
            批量下架
          </Button>,
        ]}
        scroll={{ x: 1400 }}
      />

      {/* 商品详情弹窗 */}
      <Modal
        title={
          <Space>
            <AppstoreOutlined style={{ color: '#1890ff' }} />
            商品详情
          </Space>
        }
        open={detailModalVisible}
        onCancel={() => setDetailModalVisible(false)}
        footer={null}
        width={640}
      >
        {selectedGoods && (
          <Descriptions column={2} bordered size="small">
            <Descriptions.Item label="商品编号" span={2}>
              {selectedGoods.goodsSn}
            </Descriptions.Item>
            <Descriptions.Item label="商品名称" span={2}>
              {selectedGoods.goodsName}
            </Descriptions.Item>
            <Descriptions.Item label="格口规格">
              {gridSpecMap[selectedGoods.gridSpec]?.text || '未知'}
            </Descriptions.Item>
            <Descriptions.Item label="服务类型">
              {selectedGoods.serviceTypeName}
            </Descriptions.Item>
            <Descriptions.Item label="成本价">
              ¥{selectedGoods.costPrice.toFixed(2)}
            </Descriptions.Item>
            <Descriptions.Item label="初始价格">
              ¥{selectedGoods.initialPrice.toFixed(2)}
            </Descriptions.Item>
            <Descriptions.Item label="超时价格">
              ¥{selectedGoods.overtimePrice.toFixed(2)}/天
            </Descriptions.Item>
            <Descriptions.Item label="免费天数">
              {selectedGoods.freeDays}天
            </Descriptions.Item>
            <Descriptions.Item label="积分抵扣">
              {selectedGoods.pointDeduct === 1 ? '支持' : '不支持'}
            </Descriptions.Item>
            <Descriptions.Item label="抵扣上限">
              {selectedGoods.pointDeduct === 1 ? `${selectedGoods.pointDeductLimit}%` : '-'}
            </Descriptions.Item>
            <Descriptions.Item label="商品状态" span={2}>
              <Tag color={goodsStatusMap[selectedGoods.goodsStatus]?.color || 'default'}>
                {goodsStatusMap[selectedGoods.goodsStatus]?.text || '未知'}
              </Tag>
            </Descriptions.Item>
          </Descriptions>
        )}
      </Modal>
    </>
  )
}

export default ProductList